import sys

def parse(tokens, pos, symbol, memo):
    key=(pos,symbol)
    if key in memo:
        return memo[key]
    results=[]
    if symbol=='S':
        results+=parse(tokens,pos,'A',memo)
    elif symbol=='A':
        results+=parse(tokens,pos,'B',memo)
    elif symbol=='B':
        results+=parse(tokens,pos,'C',memo)
    elif symbol=='C':
        # C -> D
        results+=parse(tokens,pos,'D',memo)
        # C -> '[' C ']'
        if pos < len(tokens) and tokens[pos]=='[':
            for mid in parse(tokens,pos+1,'C',memo):
                if mid < len(tokens) and tokens[mid]==']':
                    results.append(mid+1)
    elif symbol=='D':
        # D -> 'success'
        if pos < len(tokens) and tokens[pos]=='success':
            results.append(pos+1)
        # D -> 'because'
        if pos < len(tokens) and tokens[pos]=='because':
            results.append(pos+1)
    memo[key]=results
    return results

